const item = $input.first().json;
const source = item.source || 'webhook';
const customer_id = item.email || item.customer_id || item.user_id || 'unknown';
const customer_name = item.name || item.customer_name || customer_id;
const message = item.message || item.text || item.body || '';
const subject = item.subject || '';
const timestamp = new Date().toISOString();
const thread_id = item.thread_id || item.threadId || '';
const is_reply = !!(item.is_reply || item.in_reply_to || thread_id);

return [{
  json: { source, customer_id, customer_name, message, subject, timestamp, thread_id, is_reply }
}];

const message = $('Normalize Message').first().json;
const kbEntries = $('Read Knowledge Base').all().map(i => i.json);
const configEntries = $('Read Agent Config').all().map(i => i.json);

const config = {};
for (const entry of configEntries) { config[entry.Setting] = entry.Value; }

const kbFormatted = kbEntries.map((entry, i) => {
  const id = entry.ID || (i + 1);
  return `[KB #${id}] Category: ${entry.Category}\nQuestion Patterns: ${entry['Question Pattern']}\nApproved Answer: ${entry['Approved Answer']}\nConfidence Override: ${entry['Confidence Threshold Override'] || 'default'}`;
}).join('\n\n');

const threshold = parseInt(config.confidence_threshold || '80');

// Thread history for follow-up messages
let threadContext = '';
if (message.is_reply && message.thread_id) {
  try {
    const logEntries = $('Read Thread History').all().map(i => i.json);
    const history = logEntries
      .filter(e => e['Thread ID'] === message.thread_id)
      .sort((a, b) => new Date(a.Timestamp) - new Date(b.Timestamp))
      .map(e => '[' + e.Timestamp + '] ' + (e['Action Taken'] || 'Customer') + ': ' + (e['Original Message'] || e['Response Sent'] || '').substring(0, 200))
      .join('\n');
    if (history) threadContext = '\n\nCONVERSATION HISTORY (this is a follow-up):\n' + history;
  } catch (e) { /* no thread history */ }
}

const systemPrompt = `You are a customer support AI agent for ${config.business_name || '[Your Business Name]'}.`,
  + '\n\nYour task: analyze the incoming customer message and determine the best response.'
  + `\n\nBUSINESS VOICE: ${config.business_voice || 'Professional but friendly. Use first names. Keep responses under 150 words.'}`
  + `\n\nKNOWLEDGE BASE:\n${kbFormatted || '(No entries yet)'}`
  + `\n\nESCALATION KEYWORDS: ${config.escalation_keywords || 'urgent, refund, cancel, legal, lawyer, angry, furious, complaint, escalate'}`
  + `\n\nCONFIDENCE THRESHOLD: ${threshold}`
  + '\n\nINSTRUCTIONS:'
  + '\n1. Check for ESCALATION KEYWORDS first. If found, set action to "escalate".'
  + '\n2. Search the knowledge base semantically.'
  + '\n3. Rate confidence 0-100.'
  + `\n4. Determine action: confidence >= ${threshold} = "auto_respond", below = "needs_approval", keywords = "escalate".`
  + '\n5. Generate a natural, personalized response.'
  + '\n6. Return ONLY valid JSON:'
  + '\n{'
  + '\n  "classification": "[category or Unknown]",'
  + '\n  "confidence": [0-100],'
  + '\n  "action": "auto_respond" | "needs_approval" | "escalate",'
  + '\n  "matched_kb_id": [KB ID or null],'
  + '\n  "response": "[response text]",'
  + '\n  "reasoning": "[one sentence]",'
  + '\n  "detected_intent": "[what customer wants]",'
  + '\n  "sentiment": "positive" | "neutral" | "frustrated" | "angry"'
  + '\n}'
  + threadContext;

const userMessage = `From: ${message.customer_name} (${message.customer_id})\nSubject: ${message.subject || '(none)'}\nMessage: ${message.message}`;

return [{ json: { systemPrompt, userMessage, confidence_threshold: threshold, config, original_message: message } }];

const response = $input.first().json;
const context = $('Format Context for Claude').first().json;
const originalMessage = context.original_message;
const threshold = context.confidence_threshold || 80;

let parsed;
try {
  const text = response.content[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : text);
} catch (e) {
  parsed = {
    classification: 'Unknown', confidence: 0, action: 'needs_approval',
    matched_kb_id: null, response: "I apologize, but I wasn't able to process your request. A team member will assist you shortly.",
    reasoning: 'Failed to parse AI response: ' + e.message, detected_intent: 'unknown', sentiment: 'neutral'
  };
}

if (parsed.action === 'auto_respond' && parsed.confidence < threshold) {
  parsed.action = 'needs_approval';
  parsed.reasoning += ' (confidence below threshold, routing to human)';
}

return [{
  json: {
    ...parsed,
    source: originalMessage.source, customer_id: originalMessage.customer_id,
    customer_name: originalMessage.customer_name, message: originalMessage.message,
    subject: originalMessage.subject, timestamp: originalMessage.timestamp,
    thread_id: originalMessage.thread_id, is_reply: originalMessage.is_reply,
    config: context.config
  }
}];

const data = $input.first().json;
const signature = (data.config && data.config.welcome_signature) || 'Best regards, Support Team';
const formattedResponse = data.response + '\n\n' + signature;

return [{
  json: {
    Timestamp: data.timestamp, 'Source Channel': data.source,
    'Customer Identifier': data.customer_id,
    'Original Message': (data.message || '').substring(0, 500),
    'AI Classification': data.classification, 'Confidence Score': data.confidence,
    'Action Taken': 'Auto-responded',
    'Response Sent': formattedResponse,
    'Response Source': 'Auto (KB #' + (data.matched_kb_id || 'AI') + ')',
    'Thread ID': data.thread_id || '', 'Resolution Status': 'Resolved',
    'Time to Response': Math.floor((Date.now() - new Date(data.timestamp).getTime()) / 1000),
    formatted_response: formattedResponse, matched_kb_id: data.matched_kb_id,
    customer_name: data.customer_name, source: data.source,
    sentiment: data.sentiment, detected_intent: data.detected_intent, reasoning: data.reasoning
  }
}];

const pendingData = $('Prepare Pending Data').first().json;
const teamMembers = $('Read Team Directory').all().map(i => i.json);
const classification = pendingData._classification || 'Unknown';

// Find reviewer by category ownership
let reviewer = teamMembers.find(member => {
  if (String(member.Status).toLowerCase() === 'away') return false;
  const categories = (member['Owns Categories'] || '').split(',').map(c => c.trim().toLowerCase());
  return categories.includes(classification.toLowerCase());
});

// Fallback: default handler
if (!reviewer) {
  reviewer = teamMembers.find(m =>
    String(m['Is Default']).toLowerCase() === 'yes' &&
    String(m.Status).toLowerCase() !== 'away'
  );
}

// Final fallback: first active member
if (!reviewer) {
  reviewer = teamMembers.find(m => String(m.Status).toLowerCase() !== 'away')
    || teamMembers[0]
    || { Name: 'Support Team', Email: '', 'Slack ID': '' };
}

const msg = pendingData;
const notificationText = `*New Support Message Needs Review*\n\n` +
  `*From:* ${msg._customer_name} (${msg._customer_id})\n` +
  `*Category:* ${msg._classification} | *Confidence:* ${msg._confidence}% | *Sentiment:* ${msg._sentiment}\n\n` +
  `*Customer Message:*\n> ${msg['Original Message']}\n\n` +
  `*AI Draft Response:*\n> ${msg['AI Draft Response']}\n\n` +
  `*Reasoning:* ${msg._reasoning}\n\n` +
  `---\n` +
  `*To approve:* Update Status to \"Approved\" in Pending Approvals sheet (row: ${msg._pending_id})\n` +
  `*To edit:* Write your response in \"Final Response\" column, then set Status to \"Approved\"\n` +
  `*To reject:* Set Status to \"Rejected\"\n` +
  `*To add to KB:* Set \"Add to KB?\" to \"Yes\" and fill \"New KB Category\"\n\n` +
  `Or POST to the approval webhook:\n` +
  `\`/webhook/support-approval\` with \`{"action":"approve","pending_id":"${msg._pending_id}","approver":"${reviewer.Name}"}\``;

return [{
  json: {
    reviewer_name: reviewer.Name,
    reviewer_email: reviewer.Email || '',
    reviewer_slack_id: reviewer['Slack ID'] || '',
    notification_text: notificationText,
    // Pass-through for logging
    _pending_id: msg._pending_id,
    _customer_id: msg._customer_id,
    _customer_name: msg._customer_name,
    _source: msg._source,
    _classification: msg._classification,
    _confidence: msg._confidence,
    _message: msg._message,
    _timestamp: msg.Timestamp,
    _thread_id: msg._thread_id
  }
}];

const data = $('Route to Reviewer').first().json;

return [{
  json: {
    Timestamp: data._timestamp,
    'Source Channel': data._source,
    'Customer Identifier': data._customer_id,
    'Original Message': (data._message || '').substring(0, 500),
    'AI Classification': data._classification,
    'Confidence Score': data._confidence,
    'Action Taken': 'Sent to ' + data.reviewer_name + ' for approval',
    'Response Sent': '',
    'Response Source': 'Pending approval',
    'Thread ID': data._thread_id || '',
    'Resolution Status': 'Open',
    'Time to Response': 0
  }
}];

const webhook = $('Approval Webhook').first().json;
const pendingRows = $('Read Pending Approvals').all().map(i => i.json);

// Find the matching pending approval
const pendingId = webhook.pending_id || '';
let pending = pendingRows.find(r => r.ID === pendingId);

if (!pending) {
  // Try matching by customer identifier + timestamp
  pending = pendingRows.find(r =>
    r.Status === 'Pending' &&
    (!pendingId || r.ID === pendingId)
  );
}

if (!pending) {
  return [{ json: { error: 'Pending approval not found', pending_id: pendingId, status: 'error' } }];
}

const action = (webhook.action || 'approve').toLowerCase();
const approver = webhook.approver || 'Unknown';
const editedResponse = webhook.edited_response || '';
const addToKb = webhook.add_to_kb || 'No';
const newKbCategory = webhook.new_kb_category || pending['AI Classification'] || '';

let finalResponse = editedResponse || pending['AI Draft Response'] || '';
let status, responseSource;

if (action === 'approve') {
  status = 'Approved';
  responseSource = editedResponse ? 'Human-written' : 'Human-approved draft';
} else if (action === 'edit') {
  status = 'Approved';
  responseSource = 'Human-written';
  finalResponse = editedResponse;
} else if (action === 'reject') {
  status = 'Rejected';
  responseSource = 'Rejected';
  finalResponse = '';
} else {
  status = 'Approved';
  responseSource = 'Human-approved draft';
}

return [{
  json: {
    // For updating Pending Approvals sheet
    ID: pending.ID,
    Status: status,
    'Approved By': approver,
    'Final Response': finalResponse,
    'Add to KB?': addToKb,
    'New KB Category': newKbCategory,
    // For downstream: Conversation Log
    Timestamp: new Date().toISOString(),
    'Source Channel': pending['Source Channel'] || 'webhook',
    'Customer Identifier': pending['Customer Identifier'],
    'Original Message': pending['Original Message'],
    'AI Classification': pending['AI Classification'] || '',
    'Confidence Score': pending['Confidence Score'] || 0,
    'Action Taken': action === 'reject' ? 'Rejected by ' + approver : 'Approved by ' + approver,
    'Response Sent': finalResponse,
    'Response Source': responseSource,
    'Thread ID': '',
    'Resolution Status': action === 'reject' ? 'Rejected' : 'Resolved',
    'Time to Response': 0,
    // Control flags
    _action: action,
    _add_to_kb: addToKb,
    _new_kb_category: newKbCategory,
    _customer_name: pending['Customer Identifier'],
    _original_message: pending['Original Message'],
    _final_response: finalResponse,
    _approver: approver
  }
}];

const data = $('Parse Claude Response').first().json;
const teamMembers = $('Read Team Directory (Escalation)').all().map(i => i.json);
const classification = data.classification || 'Unknown';

let owner = teamMembers.find(m => {
  if (String(m.Status).toLowerCase() === 'away') return false;
  const cats = (m['Owns Categories'] || '').split(',').map(c => c.trim().toLowerCase());
  return cats.includes(classification.toLowerCase());
});
if (!owner) owner = teamMembers.find(m => String(m['Is Default']).toLowerCase() === 'yes' && String(m.Status).toLowerCase() !== 'away');
if (!owner) owner = teamMembers.find(m => String(m.Status).toLowerCase() !== 'away') || teamMembers[0] || { Name: 'Support Team', 'Slack ID': '', Email: '' };

const alertText = '*URGENT: Support Message Requires Immediate Attention*\n\n' +
  '*From:* ' + data.customer_name + ' (' + data.customer_id + ')\n' +
  '*Category:* ' + data.classification + ' | *Sentiment:* ' + data.sentiment + '\n' +
  '*Intent:* ' + data.detected_intent + '\n\n' +
  '*Full Message:*\n> ' + data.message + '\n\n' +
  '*AI Reasoning:* ' + data.reasoning + '\n\n' +
  '_Routed to: ' + owner.Name + '_';

return [{ json: {
  owner_name: owner.Name, owner_email: owner.Email || '', owner_slack_id: owner['Slack ID'] || '',
  alert_text: alertText,
  customer_id: data.customer_id, customer_name: data.customer_name, source: data.source,
  message: data.message, subject: data.subject, timestamp: data.timestamp,
  thread_id: data.thread_id, classification: data.classification, confidence: data.confidence,
  sentiment: data.sentiment, reasoning: data.reasoning
} }];

const data = $input.first().json;
return [{ json: {
  Category: data._new_kb_category || data['AI Classification'] || 'General',
  'Question Pattern': (data._original_message || data['Original Message'] || '').substring(0, 300),
  'Approved Answer': data._final_response || data['Final Response'] || data['Response Sent'] || '',
  Source: 'Learned from ' + (data._approver || 'human') + ' on ' + new Date().toISOString().split('T')[0],
  'Times Used': 0,
  'Last Used': '',
  'Confidence Threshold Override': ''
} }];

const configEntries = $('Read Config (Follow-Up)').all().map(i => i.json);
const logEntries = $('Read Conversation Log (Follow-Up)').all().map(i => i.json);

const config = {};
for (const entry of configEntries) { config[entry.Setting] = entry.Value; }
const followUpHours = parseInt(config.follow_up_check_hours || '4');
const cutoff = new Date(Date.now() - followUpHours * 60 * 60 * 1000);
const criticalCutoff = new Date(Date.now() - followUpHours * 2 * 60 * 60 * 1000);

const staleItems = logEntries.filter(entry => {
  const status = (entry['Resolution Status'] || '').toLowerCase();
  if (status !== 'open' && status !== 'escalated') return false;
  const ts = new Date(entry.Timestamp);
  return ts < cutoff;
}).map(entry => {
  const ts = new Date(entry.Timestamp);
  const hoursWaiting = Math.round((Date.now() - ts.getTime()) / (60 * 60 * 1000));
  const isCritical = ts < criticalCutoff;
  return {
    ...entry,
    _hours_waiting: hoursWaiting,
    _is_critical: isCritical
  };
});

if (staleItems.length === 0) {
  return [{ json: { _no_stale: true, message: 'No stale conversations found' } }];
}

// Build summary alert
let alertText = '*Stale Conversation Alert*\n\n';
alertText += `Found ${staleItems.length} unresolved conversation(s):\n\n`;
for (const item of staleItems) {
  const prefix = item._is_critical ? '🔴 CRITICAL' : '🟡 Reminder';
  alertText += `${prefix} | ${item['Customer Identifier']} | ${item._hours_waiting}h waiting | ${item['AI Classification'] || 'Unclassified'} | Status: ${item['Resolution Status']}\n`;
}

return [{ json: {
  _no_stale: false,
  alert_text: alertText,
  stale_count: staleItems.length,
  digest_channel: config.digest_slack_channel || '',
  digest_email: config.digest_email || ''
} }];

const configEntries = $('Read Config (Digest)').all().map(i => i.json);
const logEntries = $('Read Conversation Log (Digest)').all().map(i => i.json);

const config = {};
for (const entry of configEntries) { config[entry.Setting] = entry.Value; }

// Filter to last 24 hours
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);
const recent = logEntries.filter(e => new Date(e.Timestamp) > cutoff);

// Build summary data for Claude
const summary = recent.map(e => {
  return `[${e.Timestamp}] ${e['Source Channel']} | ${e['Customer Identifier']} | ${e['AI Classification']} | Confidence: ${e['Confidence Score']} | Action: ${e['Action Taken']} | Status: ${e['Resolution Status']} | Response Time: ${e['Time to Response']}s`;
}).join('\n');

const digestPrompt = `Analyze the following 24 hours of support activity and generate a concise operations digest.

DATA:
${summary || '(No activity in the last 24 hours)'}

Generate a digest with these sections:
1. SUMMARY: Total messages, auto-resolved count, human-handled count, escalated count, average response time
2. TOP TOPICS: The 5 most frequent question categories today
3. KNOWLEDGE GAPS: Questions the agent could not answer confidently. These are candidates for new KB entries.
4. SENTIMENT OVERVIEW: Breakdown of customer sentiment
5. STALE ITEMS: Any unresolved conversations older than 24 hours
6. RECOMMENDATION: One specific suggestion for improving the system

Keep it under 500 words. Use bullet points. Be specific with numbers.`;

return [{ json: {
  digestPrompt,
  total_messages: recent.length,
  digest_channel: config.digest_slack_channel || '',
  digest_email: config.digest_email || '',
  business_name: config.business_name || 'Support'
} }];

const response = $input.first().json;
const context = $('Prepare Digest Data').first().json;

let digestText = '';
try {
  digestText = response.content[0].text;
} catch (e) {
  digestText = 'Failed to generate digest: ' + e.message;
}

const header = `*Daily Support Digest — ${context.business_name}*\n` +
  `_${new Date().toISOString().split('T')[0]} | ${context.total_messages} messages in last 24h_\n\n`;

return [{ json: {
  digest_text: header + digestText,
  digest_channel: context.digest_channel,
  digest_email: context.digest_email
} }];

const logEntries = $('Read Log for Rate Limit').all().map(i => i.json);
const config = $('Parse Claude Response').first().json.config || {};
const maxPerHour = parseInt(config.max_auto_responses_per_hour || '50');
const autoRespond = (config.auto_respond_enabled || 'TRUE').toUpperCase() === 'TRUE';

// Count auto-responses in the last hour
const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
const recentAutoCount = logEntries.filter(e => {
  return (e['Action Taken'] || '').includes('Auto-responded') &&
    new Date(e.Timestamp) > oneHourAgo;
}).length;

const data = $input.first().json;

if (!autoRespond || recentAutoCount >= maxPerHour) {
  // Redirect to approval path
  return [{ json: { ...data, _rate_limited: true, _rate_reason: !autoRespond ? 'auto-respond disabled' : 'rate limit reached (' + recentAutoCount + '/' + maxPerHour + ')' } }];
}

return [{ json: { ...data, _rate_limited: false } }];
